from pathlib import Path
import re,html
from urllib.parse import quote
r=Path.cwd();old=(r/'docs/design/ui-c2/UI_C2_A_Prototype.html').read_text(encoding='utf-8');new=(r/'docs/design/ui-c2/UI_C2_HOME_Prototype.html').read_text(encoding='utf-8');baseStyle=re.search(r'<style>(.*?)</style>',old,re.S).group(1);newStyle=re.search(r'<style>(.*?)</style>',new,re.S).group(1);sym=(r/'build/ui-c2-home/home-symbols.html').read_text(encoding='utf-8');r2=(r/'build/ui-c2-home/r2-home-fragment.html').read_text(encoding='utf-8');final=(r/'build/ui-c2-home/home-fragment.html').read_text(encoding='utf-8')
def frame(theme,body,style,variant=''):
 return '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><style>'+style+'html,body{margin:0;padding:0;overflow:hidden}.device{max-width:none;outline:none;box-shadow:none;border-radius:16px}</style></head><body>'+sym+f'<div class="device {variant}" data-theme="{theme}">'+body+'</div></body></html>'
def iframe(doc):return '<iframe title="合成HTML设计原型，非Android截图" srcdoc="'+html.escape(doc,quote=True)+'" width="360" height="800"></iframe>'
def reference(theme):
 uri=(r/f'build/ui-c2-home/reference/ui-reference-{theme}.png').as_uri()
 x,y,w,h=(44,104,266,582) if theme=='light' else (23,145,284,542)
 scale=360/w;innerh=h*scale;offset=(800-innerh)/2
 doc=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><style>*{{box-sizing:border-box}}html,body{{margin:0;overflow:hidden}}body{{background:{'#f6f5f1' if theme=='light' else '#111815'}}}.crop{{position:absolute;left:0;top:{offset}px;width:360px;height:{innerh}px;overflow:hidden;border-radius:16px}}img{{position:absolute;left:{-x*scale}px;top:{-y*scale}px;width:{(1222 if theme=='light' else 1214)*scale}px;max-width:none}}</style><div class="crop"><img alt="UI-C1冻结设计图的首页区域，仅作设计参考，非设备截图" src="{uri}"></div></html>'''
 return iframe(doc)
style='''*{box-sizing:border-box}body{margin:0;background:#eeede7;color:#17221d;font:16px/1.5 system-ui,"Segoe UI","Microsoft YaHei",sans-serif}.head{padding:32px 40px 20px}.head h1{font-size:26px;font-weight:550;letter-spacing:-.02em;margin:0 0 8px}.head p{font-size:14px;color:#596a61;max-width:1120px;margin:0}.status{display:inline-block;border:1px solid #b8c5bb;border-radius:6px;padding:5px 8px;font-size:12px;color:#365f4a;margin-top:12px}.grid{display:flex;gap:32px;padding:12px 40px 24px}figure{margin:0;width:360px;flex:none}h2{font-size:17px;font-weight:550;line-height:1.4;margin:0 0 12px}h2 small{display:block;font-size:12px;font-weight:400;color:#596a61;margin-top:4px}iframe{box-sizing:content-box;border:1px solid #ccd3c8;border-radius:16px;display:block;overflow:hidden;width:360px;height:800px;box-shadow:0 7px 20px #1a2d2010}figcaption{font-size:12px;line-height:1.6;color:#596a61;margin-top:12px}footer{font-size:12px;color:#596a61;border-top:1px solid #d5dbd2;margin:4px 40px;padding-top:16px;max-width:1120px}'''
for theme,ch in [('light','浅色'),('dark','深色')]:
 figures=[('原UI-C1','0dce7dd · 原设计参考图',reference(theme),'原始设计图首页裁切，保留原比例。品牌图片、金额和日期仅为历史设计演示，不进入生产界面。'),('A-R2','e24703b前已审查HTML · 历史保持',iframe(frame(theme,r2,baseStyle)),'冻结的A-R2首页模板：金额小计卡与顶栏新增仍在。本轮未覆盖原HTML及其原始截图。'),('B-HOME最终候选','当前首页 · 合成HTML原型',iframe(frame(theme,final,newStyle)),'数量卡恢复已录入总数；口径移入信息入口。搜索留顶栏，唯一圆形＋移到内容区右下角；金额能力按需展开。')]
 text='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>B-HOME '+ch+' 三列对比</title><style>'+style+'</style></head><body><header class="head"><h1>首页原设计收口 · '+ch+'三列对照</h1><p>原设计与两轮HTML样板采用相同展示宽度；历史原图按原比例呈现。右列用于核对数量小卡、圆形新增和记录节奏，不是APK截图。</p><span class="status">PROTOTYPE_ONLY / APP_VISUAL_PENDING</span></header><div class="grid">'
 for title,sub,content,caption in figures:text+=f'<figure><h2>{title}<small>{sub}</small></h2>{content}<figcaption>{caption}</figcaption></figure>'
 text+='</div><footer>参考源：feat/ui-c1-visual-redesign @ 0dce7dd；当前原型继承A-R2浅深色板。真实媒体仍MEDIA_DISPLAY_PENDING。无设备运行，不证明Android字体、IME、触控或生产MainActivity视觉。</footer></body></html>'
 (r/f'build/ui-c2-home/compare-{theme}.html').write_text(text,encoding='utf-8')
empty=final.replace('<span data-slot="total">¥21.44</span>','<span data-slot="total">—</span>').replace('截至 2026-10-26 · 非今日扣款','尚无记录 · 非今日扣款')
text='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>B-HOME 代表状态</title><style>'+style+'</style></head><body><header class="head"><h1>首页代表状态 · 空态与浏览器大字模拟</h1><p>真正空账本只有一次新增主动作；大字卡片按内容增长并纵向重排，正文可滚动。仅浏览器字体×2，非Android系统200%字体。</p><span class="status">PROTOTYPE_ONLY / APP_VISUAL_PENDING</span></header><div class="grid"><figure><h2>真正空账本<small>360×800 · 不把无记录写成0</small></h2>'+iframe(frame('light',empty,newStyle,'empty-home'))+'<figcaption>不显示两个空列表与数量卡，不显示FAB；只有“记下第一条记录”主动作。</figcaption></figure><figure><h2>浏览器字体×2<small>360×800 · 非Android系统字号</small></h2>'+iframe(frame('light',final,newStyle,'large-type'))+'<figcaption>数量卡改纵向，数字与标签可增长；固定圆形＋位于导航上方，最后一条内容可滚至其上方。</figcaption></figure></div><footer>合成HTML，不证明Android真实字体、IME、TalkBack或运行。真实0与负金额由现有生产金额组件和原Overview区分，未改算法。</footer></body></html>'
(r/'build/ui-c2-home/states.html').write_text(text,encoding='utf-8')
print('Created two comparison boards and one states board in ignored build directory.')
